// Circle with diameter AB and a chord CD perpendicular to AB at M.
// Two-argument size fixes the output box at 320 x 240, so the declared
// aspect ratio 4/3 is exact and the reserved space cannot drift.
size(320,240);
pair O=(0,0), A=(-10,0), B=(10,0), M=(-6,0);
real h=8;
pair C=M+(0,h), D=M+(0,-h);
draw(circle(O,10));
draw(A--B);
draw(C--D);
dot(A, black+2.5pt); dot(B, black+2.5pt); dot(C, black+2.5pt); dot(D, black+2.5pt); dot(M, black+2.5pt);
label("$A$",A,SW); label("$B$",B,SE); label("$C$",C,N); label("$D$",D,NE);
label("$O$",O,NE); label("$M$",M+(-1.5,-0.35),SE);
draw(M+(-0.7,0)--M+(-0.7,0.7)--M+(0,0.7));
